"use client"

import dynamic from "next/dynamic"
import { useCallback, useEffect, useMemo, useRef, useState } from "react"
import { gsap } from "gsap"
  import { Activity, AlertCircle, AlertTriangle, ArrowRight, ArrowUpRight, Bell, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, CloudSun, Cpu, Download, Droplets, FileText, Filter, Flower2, Gauge, History, Leaf, Lightbulb, LocateFixed, Map, Menu, MoreHorizontal, Plus, RadioTower, Search, Settings2, ShieldCheck, Signal, Sprout, Thermometer, Wifi, Wind, X, Zap, ZoomIn, ZoomOut } from "lucide-react"
import { initialAlerts, initialTimeline, measurements, plants as seedPlants, properties as propertySeeds, sectors, stateLabel, type Alert, type Plant, type PlantState, type Property, type TimelineEvent } from "@/lib/siaf-data"
import { MonitoringDashboard } from "@/components/monitoring-dashboard"

const PlantTwin = dynamic(() => import("@/components/plant-twin"), { ssr: false, loading: () => <div className="twin-loading"><Sprout size={30} /><span>Preparando gêmeo digital…</span></div> })
type View = "Visão geral" | "Análise de mapa" | "Plantas monitoradas" | "Monitoramento" | "Análise de IA" | "Central de alertas" | "Relatórios" | "Dispositivos e sensores" | "Configurações" | "Propriedades" | "Cultivos e setores" | "Alertas" | "Intelligence Engine" | "Histórico e intervenções"
const navGroups: { label: string; items: { name: View; icon: typeof Activity }[] }[] = [
  { label: "ACOMPANHAMENTO", items: [{ name: "Visão geral", icon: Activity }, { name: "Análise de mapa", icon: Map }, { name: "Plantas monitoradas", icon: Flower2 }, { name: "Monitoramento", icon: Gauge }] },
  { label: "INTELIGÊNCIA", items: [{ name: "Análise de IA", icon: Zap }, { name: "Central de alertas", icon: AlertTriangle }] },
  { label: "GESTÃO", items: [{ name: "Relatórios", icon: FileText }, { name: "Dispositivos e sensores", icon: Cpu }] },
]
const stateColor: Record<PlantState, string> = { baseline: "#329365", observation: "#d59d32", alert: "#dc7657", offline: "#89948b" }

function StatusTag({ state }: { state: PlantState }) { return <span className={`status-tag ${state}`}><i />{stateLabel[state]}</span> }
function MiniChart({ variant = "area", color = "#238354", height = 90 }: { variant?: "area" | "line"; color?: string; height?: number }) {
  const values = [39, 46, 41, 54, 48, 61, 55, 65, 57, 69, 63, 77, 66, 74, 67, 82, 73, 79, 72, 85, 77, 88, 81, 92]
  const points = values.map((v, i) => `${(i / (values.length - 1)) * 100},${100 - v}`).join(" ")
  return <svg className="mini-chart" viewBox="0 0 100 100" preserveAspectRatio="none" style={{ height }} aria-label="Série temporal demonstrativa" role="img"><defs><linearGradient id={`fill-${color.replace("#", "")}`} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity=".2"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs><path d={`M ${points} L 100,100 L 0,100 Z`} fill={variant === "area" ? `url(#fill-${color.replace("#", "")})` : "none"}/><polyline points={points} fill="none" stroke={color} strokeWidth="1.8" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round"/><line x1="0" y1="74" x2="100" y2="74" stroke="#d7e1d9" strokeDasharray="2 3" vectorEffect="non-scaling-stroke"/></svg>
}
function IconButton({ label, children, onClick }: { label: string; children: React.ReactNode; onClick?: () => void }) { return <button className="icon-button" aria-label={label} title={label} onClick={onClick}>{children}</button> }

function FarmMap({ property, plants, onSelect, selectedSector, onSector }: { property: Property; plants: Plant[]; onSelect: (id: string) => void; selectedSector: string; onSector: (v: string) => void }) {
  const [layersOpen, setLayersOpen] = useState(false)
  const [showPlants, setShowPlants] = useState(true)
  const [showIncidents, setShowIncidents] = useState(true)
  const [showAerial, setShowAerial] = useState(true)
  const [showStress, setShowStress] = useState(true)
  const [mapView, setMapView] = useState({ x: 0, y: 0, scale: 1 })
  const dragStart = useRef<{ x: number; y: number; offsetX: number; offsetY: number } | null>(null)
  const mapRef = useRef<HTMLDivElement>(null)
  const zoomMap = (delta: number) => setMapView(current => ({ ...current, scale: Math.min(2.7, Math.max(1, current.scale + delta)) }))
  const resetMap = () => setMapView({ x: 0, y: 0, scale: 1 })
  const startMapDrag = (event: React.PointerEvent<HTMLDivElement>) => {
    if ((event.target as Element).closest(".map-sector,.map-marker,button")) return
    event.currentTarget.setPointerCapture(event.pointerId)
    dragStart.current = { x: event.clientX, y: event.clientY, offsetX: mapView.x, offsetY: mapView.y }
  }
  const moveMap = (event: React.PointerEvent<HTMLDivElement>) => {
    if (!dragStart.current) return
    const bounds = event.currentTarget.getBoundingClientRect()
    const maxX = (bounds.width * (mapView.scale - 1)) / 2 + 80
    const maxY = (bounds.height * (mapView.scale - 1)) / 2 + 60
    setMapView(current => ({ ...current, x: Math.max(-maxX, Math.min(maxX, dragStart.current!.offsetX + event.clientX - dragStart.current!.x)), y: Math.max(-maxY, Math.min(maxY, dragStart.current!.offsetY + event.clientY - dragStart.current!.y)) }))
  }
  const stopMapDrag = () => { dragStart.current = null }
  const zoomMapAtWheel = (event: React.WheelEvent<HTMLDivElement>) => { event.preventDefault(); zoomMap(event.deltaY < 0 ? 0.12 : -0.12) }
  const plantMapPoint = (index:number) => { const sectorIndex=Math.floor(index/8); const localIndex=index%8; const x=sectorIndex<2?218+(localIndex%4)*55:sectorIndex%2===0?400+(localIndex%4)*29:535+(localIndex%4)*30; const y=sectorIndex===0?91+Math.floor(localIndex/4)*34:sectorIndex===1?174+Math.floor(localIndex/4)*34:sectorIndex===2||sectorIndex===3?92+Math.floor(localIndex/4)*48:174+Math.floor(localIndex/4)*43; return {x,y} }
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const context = gsap.context(() => {
      gsap.fromTo(".map-sector", { opacity: 0.65, scale: 0.97, transformOrigin: "center center" }, { opacity: 1, scale: 1, duration: 0.55, stagger: 0.06, ease: "power2.out" })
    }, mapRef)
    return () => context.revert()
  }, [showAerial])
  return <div className="map-visual">
    <div className="map-tools"><span className="map-location"><Map size={14}/> {property.location} <span className="coord-label">ÁREA SIMULADA</span></span><div className="map-layer-wrap"><button className="map-layer" aria-expanded={layersOpen} onClick={() => setLayersOpen(value => !value)}><Settings2 size={14}/> Camadas <ChevronDown size={13}/></button>{layersOpen&&<div className="layer-menu"><label><input type="checkbox" checked={showPlants} onChange={e=>setShowPlants(e.target.checked)}/> Plantas e sensores</label><label><input type="checkbox" checked={showIncidents} onChange={e=>setShowIncidents(e.target.checked)}/> Ocorrências</label><label><input type="checkbox" checked={showAerial} onChange={e=>setShowAerial(e.target.checked)}/> Imagem aérea simulada</label><label><input type="checkbox" checked={showStress} onChange={e=>setShowStress(e.target.checked)}/> Estresse da cultura</label><span>Mapa demonstrativo · sem georreferenciamento</span></div>}</div></div>
    <div className={`map-stage ${showAerial ? "has-aerial" : ""}`} ref={mapRef} onPointerDown={startMapDrag} onPointerMove={moveMap} onPointerUp={stopMapDrag} onPointerCancel={stopMapDrag} onWheel={zoomMapAtWheel}>
      <div className="map-tile-layer" style={{ transform: `translate3d(${mapView.x}px, ${mapView.y}px, 0) scale(${mapView.scale})` }}>
      <img className="map-aerial" src={property.mapImage} alt={`Imagem aérea simulada de ${property.name}, com duas estufas e quatro talhões`} loading="lazy" style={{ opacity: showAerial ? 1 : 0 }} />
      <svg viewBox="0 0 720 350" className="farm-svg" role="img" aria-label={`Mapa demonstrativo de ${property.name} com duas estufas e quatro talhões selecionáveis`}>
      <defs><pattern id="rows" width="10" height="10" patternTransform="rotate(23)" patternUnits="userSpaceOnUse"><path d="M 0 0 L 0 10" stroke="#8bac83" strokeWidth="2" opacity=".45"/></pattern><pattern id="rows2" width="12" height="12" patternTransform="rotate(-18)" patternUnits="userSpaceOnUse"><path d="M 0 0 L 0 12" stroke="#a2b98e" strokeWidth="2" opacity=".45"/></pattern><radialGradient id="crop-stress"><stop stopColor="#e65d5d" stopOpacity=".95"/><stop offset=".48" stopColor="#f3c64e" stopOpacity=".65"/><stop offset="1" stopColor="#48c978" stopOpacity=".1"/></radialGradient></defs>
      <rect width="720" height="350" rx="15" fill="#e8eee4" opacity={showAerial ? 0 : 1}/>
      {showStress&&plants.filter(plant=>plant.state==="alert"||plant.state==="observation").map(plant=>{const point=plantMapPoint(plants.findIndex(item=>item.id===plant.id));return <g key={`stress-${plant.id}`}><circle cx={point.x} cy={point.y} r={plant.state==="alert"?36:24} fill="url(#crop-stress)" pointerEvents="none"/><circle cx={point.x} cy={point.y} r={plant.state==="alert"?36:24} fill="none" stroke={plant.state==="alert"?"#dc7657":"#d59d32"} strokeWidth={plant.state==="alert"?2.5:1.8} opacity={plant.state==="alert"?0.9:0.7} pointerEvents="none"/></g>})}
      {[{name:"Estufa A",d:"M194 72 l198 3 -4 76 -198 -3z",x:292,y:112,p:"url(#rows)"},{name:"Estufa B",d:"M194 157 l198 0 0 76 -198 0z",x:293,y:195,p:"url(#rows2)"},{name:"Talhão 01",d:"M387 74 l130 0 4 83 -134 -3z",x:453,y:116,p:"url(#rows2)"},{name:"Talhão 02",d:"M522 75 l148 -2 7 89 -150 0z",x:596,y:119,p:"url(#rows)"},{name:"Talhão 03",d:"M387 160 l130 -3 4 80 -134 -1z",x:453,y:199,p:"url(#rows)"},{name:"Talhão 04",d:"M522 168 l148 -2 7 79 -150 0z",x:596,y:207,p:"url(#rows2)"}].map((s,i)=><g key={s.name} onClick={()=>onSector(s.name)} className="map-sector" tabIndex={0} role="button" aria-label={`Selecionar ${s.name}`} onKeyDown={e=>e.key==="Enter"&&onSector(s.name)}><path d={s.d} fill={s.name===selectedSector?"#b9d8bc":"#d3e0cb"} stroke={s.name===selectedSector?"#24804e":"#a1b79a"} strokeWidth={s.name===selectedSector?2.5:1.5} fillOpacity={s.name===selectedSector?0.7:0.48}/><path d={s.d} fill={s.p} opacity=".64"/><rect x={s.x-39} y={s.y-10} width="78" height="20" rx="10" fill="#ffffff" opacity=".92"/><text x={s.x} y={s.y+4} textAnchor="middle" fontSize="10" fontWeight="600" fill="#355441">{s.name}</text>{showIncidents&&i===2&&<circle cx="500" cy="84" r="8" fill="#dc7657" stroke="white" strokeWidth="3"/>}</g>)}
      {showPlants&&Array.from({length:48},(_,i)=>{const plant=plants[i];const {x,y}=plantMapPoint(i);const c=stateColor[plant?.state??"baseline"];return <g key={i} onClick={()=>plant&&onSelect(plant.id)} className="map-marker" tabIndex={0} role="button" aria-label={plant ? `Abrir planta ${plant.id} · ${stateLabel[plant.state]}` : "Planta sem dados"} onKeyDown={event=>(event.key==="Enter"||event.key===" ")&&plant&&onSelect(plant.id)}>{showStress&&plant&&(plant.state==="alert"||plant.state==="observation")&&<circle cx={x} cy={y} r={plant.state==="alert"?22:15} fill="url(#crop-stress)" stroke={plant.state==="alert"?"#d84e45":"#d59d32"} strokeWidth={plant.state==="alert"?2.5:1.5} opacity={plant.state==="alert"?0.95:0.8} pointerEvents="none"/>}<circle cx={x} cy={y} r="4.4" fill={c} stroke="#fff" strokeWidth="1.8"/><circle cx={x} cy={y} r="8" fill={c} opacity=".12"/></g>})}
      <g transform="translate(638 39)"><circle r="21" fill="#fff" opacity=".9"/><path d="M0 -14 L5 4 L0 0 L-5 4Z" fill="#467455"/><text y="-18" textAnchor="middle" fontSize="8" fill="#65766a">N</text></g><text x="30" y="325" fontSize="9" fill="#ffffff" stroke="#214832" strokeWidth="2.5" paintOrder="stroke">Imagem aérea ilustrativa · sem escala geográfica</text>
      </svg>
      </div>
      {showAerial&&<span className="aerial-tag"><span/> IMAGEM AÉREA SIMULADA</span>}
      <div className="map-navigation-controls" aria-label="Controles de navegação do mapa"><button type="button" onClick={()=>zoomMap(0.2)} aria-label="Aproximar mapa" title="Aproximar"><ZoomIn size={15}/></button><button type="button" onClick={()=>zoomMap(-0.2)} aria-label="Afastar mapa" title="Afastar"><ZoomOut size={15}/></button><span/><button type="button" onClick={resetMap} aria-label="Redefinir posição do mapa" title="Redefinir posição"><LocateFixed size={15}/></button></div>
      <span className="map-pan-hint">Arraste para mover · role para zoom</span>
    </div>
    <div className="map-footer"><span><span className="map-dot" style={{background:"#329365"}}/>Linha de base</span><span><span className="map-dot" style={{background:"#d59d32"}}/>Observação</span><span><span className="map-dot" style={{background:"#dc7657"}}/>Verificação</span><span><span className="map-dot" style={{background:"#89948b"}}/>Sem dados</span><span><span className="map-dot" style={{background:"#dc7657"}}/>Estresse ilustrativo</span><span className="map-count">48 plantas · 6 setores</span></div>
  </div>
}

function Header({ propertyName, onMenu, onSearch, onAlerts, alerts, count, search, setSearch }: { propertyName: string; onMenu: () => void; onSearch: () => void; onAlerts: () => void; alerts: Alert[]; count: number; search: string; setSearch: (v: string) => void }) {
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const activeAlerts = alerts.filter(alert => alert.status === "Requer verificação" || alert.status === "Em análise").slice(0, 4)
  return <header className="top-header"><div className="header-left"><IconButton label="Abrir navegação" onClick={onMenu}><Menu size={19}/></IconButton><span className="breadcrumb-dash">{propertyName}</span><ChevronRight size={14} className="header-chevron"/><span className="breadcrumb-current">Monitoramento</span></div><div className="header-right"><div className="connectivity"><span className="connection-pulse"/> <span>Dispositivos</span> <b>46/48</b></div><label className="global-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&!e.nativeEvent.isComposing&&e.keyCode!==229&&onSearch()} placeholder="Buscar planta, setor…" aria-label="Buscar planta ou setor"/><kbd>⌘ K</kbd></label><div className="notification-wrap"><IconButton label={notificationsOpen?"Fechar notificações":"Ver notificações recentes"} onClick={()=>setNotificationsOpen(value=>!value)}><Bell size={18}/>{count>0&&<span className="notification-count">{count}</span>}</IconButton>{notificationsOpen&&<div className="notification-popover" role="region" aria-label="Notificações recentes"><div className="notification-heading"><strong>Notificações</strong><span>{count} pendentes</span></div>{activeAlerts.length?activeAlerts.map(alert=><div className="notification-item" key={alert.id}><span className={`occurrence-indicator ${alert.priority.toLowerCase()}`}/><span><b>{alert.title}</b><small>{alert.plantId} · {alert.time}</small></span></div>):<p className="notification-empty">Nenhuma notificação pendente.</p>}<button type="button" className="notification-open" onClick={()=>{setNotificationsOpen(false);onAlerts()}}>Abrir central de alertas <ArrowRight size={13}/></button></div>}</div><div className="user-menu" aria-label="Usuário conectado"><span className="user-avatar">AO</span><span className="user-name">Ana Oliveira</span></div></div></header>
}

function Dashboard({ property, plants, allPlants, alerts, onPlant, onAlerts, sector, setSector, setView }: { property: Property; plants: Plant[]; allPlants: Plant[]; alerts: Alert[]; onPlant: (id: string) => void; onAlerts: () => void; sector: string; setSector: (v: string) => void; setView: (v: View) => void }) {
  const activeAlerts=alerts.filter(a=>a.status==="Requer verificação"||a.status==="Em análise"); const baseline=plants.filter(p=>p.state==="baseline").length; const altered=plants.filter(p=>p.state==="alert"||p.state==="observation").length; const online=plants.filter(p=>p.state!=="offline").length; const quality=Math.round(plants.filter(p=>p.quality>0).reduce((n,p)=>n+p.quality,0)/Math.max(online,1))
  const metrics=[{label:"Plantas monitoradas",value:String(plants.length),note:"em 6 setores",icon:Flower2,color:"green",trend:"+4 no período"},{label:"Dentro da linha de base",value:String(baseline),note:`${Math.round(baseline/plants.length*100)}% da propriedade`,icon:CheckCircle2,color:"green",trend:"Comportamento estável"},{label:"Sinais de estresse em observação",value:String(altered),note:"Exigem verificação humana",icon:Activity,color:"amber",trend:"2 novas hoje"},{label:"Alertas pendentes",value:String(activeAlerts.length),note:"Prioridade alta e média",icon:AlertTriangle,color:"coral",trend:"Revisar ocorrências"},{label:"Dispositivos conectados",value:`${online}/48`,note:"2 sem comunicação",icon:Cpu,color:"blue",trend:"96% conectados"},{label:"Qualidade dos dados",value:`${quality}%`,note:"Média simulada do sinal",icon:Signal,color:"green",trend:"+2,4% vs. anterior"}]
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-dot"/> TERÇA-FEIRA, 17 DE NOVEMBRO DE 2026</div><h1>Bom dia, Ana <span>—</span></h1><p>Acompanhe os sinais de {property.name} em um só lugar.</p></div><div className="welcome-actions"><select className="period-select" aria-label="Selecionar período"><option>Últimas 24 horas</option><option>Últimos 7 dias</option><option>Últimos 30 dias</option></select><button className="button-primary" onClick={()=>setView("Plantas monitoradas")}><Plus size={16}/> Adicionar planta</button></div></div>
    <div className="metrics-grid">{metrics.map((m,i)=><div className={`metric-card ${m.color}`} key={m.label}><div className="metric-top"><div className="metric-icon"><m.icon size={17}/></div>{i===5?<span className="metric-mini">{m.value}</span>:<span className="metric-hint">DEMO</span>}</div><div className="metric-label">{m.label}<span title={m.note}><CircleHelp size={13}/></span></div><div className="metric-value">{m.value}</div><div className="metric-foot"><span>{m.note}</span>{i===3?<span className="foot-alert">{m.trend}</span>:i===5?<span className="foot-positive"><ArrowUpRight size={12}/>{m.trend}</span>:<span className="foot-muted">{m.trend}</span>}</div></div>)}</div>
    <div className="overview-grid"><section className="panel map-panel"><div className="panel-heading"><div><div className="panel-title">Mapa de monitoramento <span className="demo-badge">DEMONSTRAÇÃO</span></div><p>{property.name} · {property.location} · 6 setores</p></div><button className="text-button" onClick={()=>setView("Análise de mapa")}>Abrir análise do mapa <ArrowRight size={14}/></button></div><FarmMap property={property} plants={allPlants} onSelect={onPlant} selectedSector={sector} onSector={setSector}/></section>
    <section className="panel alert-panel"><div className="panel-heading"><div><div className="panel-title">Ocorrências recentes <span className="alert-badge">{activeAlerts.length} abertas</span></div><p>Prioridade por necessidade de verificação</p></div><IconButton label="Ver todas as ocorrências" onClick={onAlerts}><ArrowUpRight size={17}/></IconButton></div><div className="occurrence-list">{alerts.slice(0,4).map(a=><button className="occurrence-row" key={a.id} onClick={()=>onPlant(a.plantId)}><span className={`occurrence-indicator ${a.priority.toLowerCase()}`}/><span className="occurrence-content"><strong>{a.title}</strong><small>{a.plantId} · {a.sector} <span>· {a.time}</span></small></span><span className={`priority-label ${a.priority.toLowerCase()}`}>{a.priority}</span><ChevronRight size={15}/></button>)}</div><button className="all-alerts" onClick={onAlerts}>Abrir central de alertas <ArrowRight size={14}/></button></section></div>
    <div className="lower-grid"><section className="panel trend-panel"><div className="panel-heading"><div><div className="panel-title">Evolução das alterações</div><p>Eventos observados · últimas 24 horas</p></div><select className="small-select" aria-label="Variável do gráfico"><option>Alterações fisiológicas</option><option>Qualidade do sinal</option></select></div><div className="trend-chart"><div className="chart-y-labels"><span>12</span><span>8</span><span>4</span><span>0</span></div><div className="chart-area"><div className="chart-gridlines"><i/><i/><i/><i/></div><MiniChart height={112}/><div className="chart-x-labels"><span>00h</span><span>04h</span><span>08h</span><span>12h</span><span>16h</span><span>20h</span><span>Agora</span></div></div></div><div className="chart-legend"><span><i className="legend-line"/>Eventos identificados</span><span><i className="legend-dash"/>Faixa de referência demonstrativa</span></div></section><section className="panel environment-panel"><div className="panel-heading"><div><div className="panel-title">Condições ambientais</div><p>Médias da propriedade · dados simulados</p></div><button className="more-button" aria-label="Mais opções"><MoreHorizontal size={19}/></button></div><div className="environment-grid"><div className="environment-cell"><Droplets size={16}/><span>Umidade do solo</span><b>54<small>%</small></b><div className="measure-bar"><i style={{width:"54%"}}/></div><small>faixa demonstrativa</small></div><div className="environment-cell"><Thermometer size={16}/><span>Temperatura</span><b>25,4<small>°C</small></b><div className="measure-bar"><i style={{width:"61%"}}/></div><small>ambiente estável</small></div><div className="environment-cell"><Wind size={16}/><span>Umidade do ar</span><b>68<small>%</small></b><div className="measure-bar"><i style={{width:"68%"}}/></div><small>faixa demonstrativa</small></div><div className="environment-cell"><CloudSun size={16}/><span>Luminosidade</span><b>12,4<small>klux</small></b><div className="measure-bar"><i style={{width:"76%"}}/></div><small>leitura simulada</small></div></div><div className="environment-source"><span className="connection-pulse"/> Atualizado às 10:45 <span>·</span> 4 sensores ambientais</div></section></div>
    <div className="dashboard-note"><Lightbulb size={15}/><span><strong>Sobre estes dados:</strong> Esta interface opera em modo de demonstração. Hipóteses ilustrativas não são diagnósticos e precisam de verificação humana.</span><button onClick={()=>setView("Análise de IA")}>Ver sinais recebidos <ArrowRight size={13}/></button></div>
  </>
}

function AnalysisMap({ property, plants, alerts, sector, onSector, onPlant }: { property: Property; plants: Plant[]; alerts: Alert[]; sector: string; onSector: (value: string) => void; onPlant: (id: string) => void }) {
  const openAlerts = alerts.filter(alert => alert.status === "Requer verificação" || alert.status === "Em análise")
  const offline = plants.filter(plant => plant.state === "offline")
  const averageQuality = Math.round(plants.reduce((total, plant) => total + plant.quality, 0) / Math.max(plants.length, 1))
  return <div className="map-analysis-view"><div className="welcome-row"><div><div className="eyebrow">LEITURA ESPACIAL · DEMONSTRAÇÃO</div><h1>Análise de mapa</h1><p>{property.name} · ocorrências e sinais por setor</p></div><span className="demo-badge">MAPA ILUSTRATIVO</span></div><div className="map-analysis-metrics"><div><span>Plantas na área</span><strong>{plants.length}</strong></div><div className={openAlerts.length ? "attention" : ""}><span>Hipóteses abertas</span><strong>{openAlerts.length}</strong></div><div className={offline.length ? "offline" : ""}><span>Sem comunicação</span><strong>{offline.length}</strong></div><div><span>Qualidade média</span><strong>{averageQuality}%</strong></div></div><div className="map-analysis-layout"><section className="panel map-panel"><div className="panel-heading"><div><div className="panel-title">Distribuição por setor</div><p>Selecione um marcador ou setor para explorar as plantas</p></div><span className="map-location-label"><Map size={14}/>{property.location}</span></div><FarmMap property={property} plants={plants} onSelect={onPlant} selectedSector={sector} onSector={onSector}/></section><aside className="panel map-analysis-aside"><div className="panel-heading"><div><div className="panel-title">Prioridade de verificação</div><p>Ocorrências que precisam de contexto humano</p></div></div><div className="map-alert-list">{openAlerts.length?openAlerts.map(alert=><button className="map-alert-item" type="button" key={alert.id} onClick={()=>onPlant(alert.plantId)}><span className={`occurrence-indicator ${alert.priority.toLowerCase()}`}/><span><strong>{alert.plantId} · {alert.title}</strong><small>{alert.sector} · {alert.time}</small></span><ChevronRight size={15}/></button>):<p className="notification-empty">Sem hipóteses pendentes nesta propriedade.</p>}</div><div className="map-analysis-foot"><strong>Leitura do mapa</strong><p>Os pontos e limites são ilustrativos. Confirme o estado da planta e do sensor antes de qualquer decisão operacional.</p><span><i className="map-dot"/> Linha de base <i className="map-dot amber-dot"/> Observação <i className="map-dot coral-dot"/> Verificação</span></div></aside></div></div>
}

function IntelligenceAnalysis({ property, plants, alerts, onPlant }: { property: Property; plants: Plant[]; alerts: Alert[]; onPlant: (id: string) => void }) {
  const pending = alerts.filter(alert => alert.status === "Requer verificação" || alert.status === "Em análise")
  const connected = plants.filter(plant => plant.state !== "offline").length
  const averageQuality = Math.round(plants.filter(plant => plant.quality > 0).reduce((total, plant) => total + plant.quality, 0) / Math.max(connected, 1))
  return <><div className="welcome-row"><div><div className="eyebrow">SINAIS E VERIFICAÇÕES · DADOS DEMONSTRATIVOS</div><h1>Intelligence Engine</h1><p>Veja quais plantas enviaram sinais e onde a qualidade ou o estado precisa de atenção.</p></div><span className="demo-badge large">SEM MODELO CIENTÍFICO CONECTADO</span></div><div className="ai-summary-grid"><div className="panel"><RadioTower size={17}/><span>Sinais recebidos</span><strong>{connected} / {plants.length}</strong><small>2 dispositivos sem comunicação</small></div><div className="panel"><Activity size={17}/><span>Qualidade média</span><strong>{averageQuality}%</strong><small>Leituras simuladas · última amostra 10:45</small></div><div className="panel"><AlertTriangle size={17}/><span>Exigem revisão humana</span><strong>{pending.length}</strong><small>Hipóteses não equivalem a diagnóstico</small></div></div><section className="panel ai-plants-panel"><div className="panel-heading"><div><div className="panel-title">Recebimento por planta</div><p>Estado do dispositivo, qualidade e alertas ativos</p></div><span className="demo-badge">SIMULAÇÃO</span></div><div className="ai-plant-list">{plants.map(plant=>{const alert=pending.find(item=>item.plantId===plant.id);return <button type="button" className="ai-plant-row" key={plant.id} onClick={()=>onPlant(plant.id)}><span className={`ai-signal-dot ${plant.state}`}/><span className="ai-plant-name"><strong>{plant.id}</strong><small>{plant.deviceId} · {plant.sector}</small></span><span className="ai-signal-state">{plant.state==="offline"?"Sem sinal":plant.state==="alert"?"Alteração detectada":plant.state==="observation"?"Em observação":"Recebido"}</span><span className="ai-quality"><i><b style={{width:`${plant.quality}%`}}/></i>{plant.quality?`${plant.quality}%`:"—"}</span><span className="ai-alert-state">{alert?.title??(plant.state==="offline"?"Verificar conexão":"Sem alerta")}</span><ChevronRight size={15}/></button>})}</div><div className="science-note"><Lightbulb size={14}/> O motor científico ainda não está conectado. Esta tela mostra apenas integridade do sinal e hipóteses demonstrativas; não gera recomendações de manejo.</div></section></>
}

function PlantList({ plants, onPlant, onAdd }: { plants: Plant[]; onPlant: (id: string) => void; onAdd: () => void }) {
  const [query,setQuery]=useState(""); const [filter,setFilter]=useState("Todas as condições"); const [page,setPage]=useState(1)
  const filtered=plants.filter(p=>(`${p.id} ${p.sector} ${p.variety} ${p.deviceId}`.toLowerCase().includes(query.toLowerCase()))&&(filter==="Todas as condições"||stateLabel[p.state]===filter)); const size=8; const pages=Math.max(1,Math.ceil(filtered.length/size));
  return <><div className="page-toolbar"><label className="table-search"><Search size={16}/><input placeholder="Buscar por ID, setor ou dispositivo" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}}/></label><select className="period-select" value={filter} onChange={e=>setFilter(e.target.value)}><option>Todas as condições</option>{Object.values(stateLabel).map(x=><option key={x}>{x}</option>)}</select><button className="button-primary" onClick={onAdd}><Plus size={16}/> Cadastrar planta</button></div><div className="panel table-panel"><div className="table-topline"><span>{filtered.length} plantas encontradas</span><span>Dados demonstrativos · última leitura às 10:45</span></div><div className="table-scroll"><table><thead><tr><th>IDENTIFICAÇÃO</th><th>ESPÉCIE / VARIEDADE</th><th>SETOR</th><th>ESTÁGIO</th><th>DISPOSITIVO</th><th>CONDIÇÃO</th><th>QUALIDADE</th><th/></tr></thead><tbody>{filtered.slice((page-1)*size,page*size).map(p=><tr key={p.id} onClick={()=>onPlant(p.id)}><td><div className="table-plant"><span className="plant-thumb"><Leaf size={16}/></span><strong>{p.id}</strong></div></td><td><span className="species">Tomate <i>· {p.variety}</i></span></td><td>{p.sector}</td><td>{p.stage}</td><td><span className="device-code"><Cpu size={12}/>{p.deviceId}</span></td><td><StatusTag state={p.state}/></td><td><span className="quality-cell"><i style={{width:`${p.quality}%`}}/>{p.quality?`${p.quality}%`:"—"}</span></td><td><ChevronRight size={15}/></td></tr>)}</tbody></table></div><div className="table-pagination"><span>Exibindo {filtered.length?((page-1)*size+1):0}–{Math.min(page*size,filtered.length)} de {filtered.length} plantas</span><div><button disabled={page<=1} onClick={()=>setPage(page-1)} aria-label="Página anterior"><ChevronLeft size={15}/></button><span>{page} / {pages}</span><button disabled={page>=pages} onClick={()=>setPage(page+1)} aria-label="Próxima página"><ChevronRight size={15}/></button></div></div></div></>
}

function PlantProfile({ plant, plants, timeline, onBack, onAddNote }: { plant: Plant; plants: Plant[]; timeline: TimelineEvent[]; onBack: () => void; onAddNote: () => void }) {
  const history=timeline.filter(e=>e.plantId===plant.id); const samples=measurements.filter(m=>m.plantId===plant.id&&m.variable==="Sinal eletrofisiológico")
  return <><button className="back-link" onClick={onBack}><ChevronLeft size={15}/> Voltar para plantas</button><div className="profile-heading"><div><div className="eyebrow">GÊMEO FISIOLÓGICO DIGITAL <span className="demo-badge">DEMONSTRAÇÃO</span></div><h1>{plant.id} <span>·</span> Tomate {plant.variety}</h1><p>{plant.species} · {plant.stage} · {plant.sector} · Cadastrada em {plant.registered}</p></div><button className="button-secondary" onClick={onAddNote}><Plus size={15}/> Registrar evento</button></div><div className="profile-grid"><section className="panel twin-panel"><div className="panel-heading"><div><div className="panel-title">Digital Physiological Twin</div><p>Gêmeo 3D demonstrativo · arraste, role ou use os controles</p></div><span className="view-toggle"><span/> Modelo 3D GLB</span></div><div className="twin-stage"><div className="twin-grid-bg"/><PlantTwin/><div className="twin-disclaimer">A aparência não representa medição fisiológica</div></div><div className="twin-identity"><div className="twin-avatar"><Sprout size={21}/></div><div><strong>{plant.id}</strong><span>Dispositivo {plant.deviceId} · conectado</span></div><StatusTag state={plant.state}/></div></section><section className="panel condition-panel"><div className="panel-heading"><div><div className="panel-title">Condição estimada</div><p>Inferência demonstrativa · 10:42</p></div><span className="condition-icon"><Activity size={17}/></span></div><div className={`hypothesis-box ${plant.state}`}><div className="hypothesis-kicker">HIPÓTESE ILUSTRATIVA · NÃO É DIAGNÓSTICO</div><h3>{plant.state==="offline"?"Inconclusivo":plant.state==="alert"?(plant.id==="T-024"?"Possível alteração compatível com déficit hídrico":"Alteração em relação à linha de base individual"):"Comportamento dentro da linha de base"}</h3><p>{plant.state==="offline"?"Dados insuficientes ou ausência de comunicação para estimar uma condição.":"Evidências demonstrativas: variação do sinal normalizado e mudança nas condições ambientais."}</p></div><div className="confidence-row"><span>Confiança da análise <CircleHelp size={13}/></span><b>{plant.state==="offline"?"Não estimável":"Moderada · simulada"}</b></div><div className="quality-row"><span>Qualidade dos dados</span><b>{plant.quality?`${plant.quality}% · simulada`:"Sem dados recentes"}</b></div><div className="confidence-track"><i style={{width:plant.state==="offline"?"0%":"64%"}}/></div><div className="limitation-note"><ShieldCheck size={15}/><span>Hipótese sujeita à verificação humana. Não constitui recomendação de manejo.</span></div><button className="text-button full-link" onClick={()=>{window.dispatchEvent(new CustomEvent("siaf-navigate",{detail:"Intelligence Engine"}))}}>Ver análise completa <ArrowRight size={14}/></button></section></div><div className="profile-detail-grid"><section className="panel profile-chart-panel"><div className="panel-heading"><div><div className="panel-title">Sinal eletrofisiológico</div><p>Série normalizada · unidade arbitrária (u.a.)</p></div><select className="small-select" aria-label="Período do sinal"><option>Últimas 24 horas</option><option>Últimos 7 dias</option></select></div><div className="signal-plot"><div className="plot-axis"><span>1,0</span><span>0,5</span><span>0,0</span><span>-0,5</span><span>-1,0</span></div><div className="plot-main"><div className="plot-grid"><i/><i/><i/><i/><i/></div><svg viewBox="0 0 600 150" preserveAspectRatio="none" role="img" aria-label="Gráfico demonstrativo do sinal eletrofisiológico normalizado"><path d="M0 75 C20 54 28 93 46 76 S70 40 88 69 S112 97 131 75 S153 58 170 80 S194 105 211 72 S235 42 251 69 S272 91 289 76 S314 37 330 71 S350 105 368 77 S389 50 409 75 S431 95 449 72 S475 44 492 75 S519 101 537 72 S569 58 600 77" fill="none" stroke="#288654" strokeWidth="2.3" vectorEffect="non-scaling-stroke"/><path d="M0 75 C20 54 28 93 46 76 S70 40 88 69 S112 97 131 75 S153 58 170 80 S194 105 211 72 S235 42 251 69 S272 91 289 76 S314 37 330 71 S350 105 368 77 S389 50 409 75 S431 95 449 72 S475 44 492 75 S519 101 537 72 S569 58 600 77" fill="none" stroke="#288654" strokeOpacity=".12" strokeWidth="9" vectorEffect="non-scaling-stroke"/></svg><div className="plot-times"><span>00:00</span><span>04:00</span><span>08:00</span><span>12:00</span><span>16:00</span><span>20:00</span><span>Agora</span></div></div></div><div className="trace-foot"><span><i/>Sinal processado · {samples.length} amostras</span><span>Origem: {plant.deviceId}-S5 · qualidade {plant.quality}%</span></div></section><section className="panel"><div className="panel-heading"><div><div className="panel-title">Variáveis ambientais</div><p>Última leitura · valores demonstrativos</p></div><button className="more-button" aria-label="Mais informações"><MoreHorizontal size={19}/></button></div><div className="profile-environment"><div><Droplets/><span>Umidade do solo</span><b>{plant.soil}%</b><small>{plant.deviceId}-S1 · 10:45</small></div><div><Thermometer/><span>Temperatura</span><b>{plant.temperature.toFixed(1).replace(".",",")}°C</b><small>{plant.deviceId}-S2 · 10:45</small></div><div><Wind/><span>Umidade do ar</span><b>68%</b><small>{plant.deviceId}-S3 · 10:45</small></div></div></section></div><section className="panel history-panel"><div className="panel-heading"><div><div className="panel-title">Histórico individual</div><p>Eventos e observações vinculados a esta planta</p></div><button className="text-button" onClick={onAddNote}><Plus size={14}/> Registrar evento</button></div>{history.length?<div className="timeline">{history.map(e=><div className="timeline-item" key={e.id}><div className="timeline-mark"><History size={14}/></div><div><strong>{e.type}</strong><p>{e.description}</p><small>{e.date} · {e.person}</small></div></div>)}</div>:<div className="empty-state">Ainda não há eventos registrados para esta planta.</div>}</section></>
}

function AlertReviewDialog({ alert, status, note, setNote, onCancel, onSubmit }: { alert: Alert; status: Alert["status"]; note: string; setNote: (value: string) => void; onCancel: () => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) {
  const title = status === "Em análise" ? "Iniciar análise" : status === "Verificação registrada" ? "Registrar resultado da verificação" : "Rejeitar hipótese"
  return <div className="dialog-backdrop" role="presentation" onMouseDown={event => event.target === event.currentTarget && onCancel()}><form className="dialog-card" role="dialog" aria-modal="true" aria-labelledby="review-dialog-title" onSubmit={onSubmit}><button type="button" className="dialog-close" onClick={onCancel} aria-label="Fechar"><X size={18}/></button><div className="dialog-icon"><ShieldCheck size={20}/></div><h2 id="review-dialog-title">{title}</h2><p>{alert.plantId} · {alert.title}. Registre o que foi verificado antes de confirmar.</p><label className="form-label">Registro da revisão<textarea autoFocus required minLength={8} rows={4} value={note} onChange={event => setNote(event.target.value)} placeholder="Ex.: inspeção visual realizada; sensor conferido; evidências observadas…"/></label><div className="dialog-demo"><Lightbulb size={14}/> A decisão e o contexto ficam vinculados a esta ocorrência nesta sessão.</div><div className="dialog-actions"><button type="button" className="button-secondary" onClick={onCancel}>Cancelar</button><button type="submit" className="button-primary">Confirmar ação</button></div></form></div>
}

function AlertsView({ alerts, plants, onReview, onPlant }: { alerts: Alert[]; plants: Plant[]; onReview: (alert: Alert, status: Alert["status"], note?: string) => void; onPlant: (id: string) => void }) {
  const [filter,setFilter]=useState("Todos"); const [reviewing,setReviewing]=useState<{alert:Alert;status:Alert["status"]}|null>(null); const [reviewNote,setReviewNote]=useState(""); const list=alerts.filter(a=>filter==="Todos"||a.status===filter)
  const openReview=(alert:Alert,status:Alert["status"])=>{setReviewNote("");setReviewing({alert,status})}
  const submitReview=(event:React.FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!reviewing||reviewNote.trim().length<8)return;onReview(reviewing.alert,reviewing.status,reviewNote.trim());setReviewing(null);setReviewNote("")}
  return <><div className="welcome-row"><div><div className="eyebrow">CENTRAL DE OCORRÊNCIAS</div><h1>Alertas e verificações</h1><p>Registre o que foi observado antes de concluir uma verificação.</p></div><select className="period-select" value={filter} onChange={e=>setFilter(e.target.value)}><option>Todos</option><option>Requer verificação</option><option>Em análise</option><option>Verificação registrada</option><option>Hipótese rejeitada</option></select></div><div className="alert-summary"><div><AlertTriangle/><b>{alerts.filter(a=>a.priority==="Alta"&&a.status==="Requer verificação").length}</b><span>Prioridade alta</span></div><div><Clock3/><b>{alerts.filter(a=>a.status==="Requer verificação").length}</b><span>Aguardando análise</span></div><div><CheckCircle2/><b>{alerts.filter(a=>a.status==="Verificação registrada").length}</b><span>Verificações registradas</span></div></div><div className="panel alerts-table"><div className="table-scroll"><table><thead><tr><th>OCORRÊNCIA</th><th>PLANTA / SETOR</th><th>PRIORIDADE</th><th>STATUS</th><th>REVISÃO HUMANA</th></tr></thead><tbody>{list.map(a=>{const plant=plants.find(p=>p.id===a.plantId);return <tr key={a.id}><td><strong>{a.title}</strong><small className="table-sub">{a.type} · hoje às {a.time}</small>{a.reviewNote&&<small className="review-note">Registro: {a.reviewNote}</small>}</td><td><button className="link-cell" onClick={()=>onPlant(a.plantId)}>{a.plantId} · {plant?.sector}</button></td><td><span className={`priority-label ${a.priority.toLowerCase()}`}>{a.priority}</span></td><td><span className={`status-tag ${a.status==="Requer verificação"?"alert":a.status==="Verificação registrada"?"baseline":a.status==="Hipótese rejeitada"?"offline":"observation"}`}><i/>{a.status}</span></td><td>{a.status==="Requer verificação"||a.status==="Em análise"?<div className="row-actions">{a.status==="Requer verificação"&&<button onClick={()=>openReview(a,"Em análise")}>Iniciar análise</button>}<button className="action-confirm" onClick={()=>openReview(a,"Verificação registrada")}>Registrar resultado</button><button className="action-reject" onClick={()=>openReview(a,"Hipótese rejeitada")}>Rejeitar hipótese</button></div>:<span className="done-label"><Check size={13}/>{a.reviewedAt?`Registrado ${a.reviewedAt}`:"Encerrado"}</span>}</td></tr>})}</tbody></table></div><div className="science-note"><Lightbulb size={15}/> Cada mudança exige uma nota de inspeção ou a justificativa da rejeição; nenhuma hipótese gera recomendação automática de manejo.</div></div>{reviewing&&<AlertReviewDialog alert={reviewing.alert} status={reviewing.status} note={reviewNote} setNote={setReviewNote} onCancel={()=>setReviewing(null)} onSubmit={submitReview}/>}</>
}

function GenericView({ view, property, properties, selectedPropertyId, plants, alerts, timeline, setView, onPlant, onCsv, onSelectProperty, onSelectSector, sector }: { view: View; property: Property; properties: Property[]; selectedPropertyId: string; plants: Plant[]; alerts: Alert[]; timeline: TimelineEvent[]; setView: (v: View) => void; onPlant: (id: string) => void; onCsv: () => void; onSelectProperty: (id: string) => void; onSelectSector: (sector: string) => void; sector: string }) {
  if(view==="Plantas monitoradas") return <><div className="welcome-row"><div><div className="eyebrow">CADASTRO INDIVIDUAL</div><h1>Plantas monitoradas</h1><p>Indivíduos, sensores associados e estado de monitoramento.</p></div></div><PlantList plants={plants} onPlant={onPlant} onAdd={()=>window.dispatchEvent(new Event("siaf-add-plant"))}/></>
  if(view==="Análise de mapa") return <AnalysisMap property={property} plants={plants} alerts={alerts} sector={sector} onSector={onSelectSector} onPlant={onPlant}/>
  if(view==="Central de alertas"||view==="Alertas") return <AlertsView alerts={alerts} plants={plants} onReview={(alert,status,note)=>{window.dispatchEvent(new CustomEvent("siaf-update-alert",{detail:{...alert,status,reviewNote:note,reviewedAt:new Date().toLocaleString("pt-BR")}}))}} onPlant={onPlant}/>
  if(view==="Monitoramento") return <MonitoringDashboard property={property} plants={plants}/>
  if(view==="Propriedades"||view==="Cultivos e setores") return <><div className="welcome-row"><div><div className="eyebrow">ORGANIZAÇÃO DA OPERAÇÃO</div><h1>{view}</h1><p>Explore a propriedade, seus setores e as plantas monitoradas.</p></div><button className="button-secondary" onClick={()=>setView("Análise de mapa")}><Map size={15}/> Abrir mapa</button></div>{view==="Propriedades"&&<div className="property-chooser">{properties.map(item=><button type="button" key={item.id} className={`property-choice ${item.id===selectedPropertyId?"selected":""}`} onClick={()=>onSelectProperty(item.id)}><span className="property-choice-icon"><Map size={16}/></span><span className="property-choice-copy"><strong>{item.name}</strong><small>{item.location} · {item.area}</small></span><span className="property-choice-status"><i/>{item.id===selectedPropertyId?"Selecionada":"Demonstração"}</span></button>)}</div>}<div className="property-card"><div className="property-cover"><div className="cover-lines"/><div className="property-label"><span className="property-mark"><Leaf/></span><span>PROPRIEDADE DEMONSTRATIVA</span></div><div className="property-title">{property.name}</div><div className="property-location"><Map size={14}/> {property.location} · {property.area} monitorados · {property.crop}</div></div><div className="property-stats"><div><span>Setores</span><b>06</b></div><div><span>Plantas</span><b>{plants.length}</b></div><div><span>Dispositivos</span><b>48</b></div><div><span>Monitoramento</span><b className="green-status">Ativo · demonstração</b></div></div><div className="sector-grid">{sectors.map((s,i)=><button className="sector-card" key={s} onClick={()=>{onSelectSector(s);setView("Plantas monitoradas")}}><div className={`sector-art sector-${i}`}><Sprout size={24}/><span>{i<2?"ESTUFA":"TALHÃO"} 0{i<2?i+1:i-1}</span></div><div className="sector-info"><strong>{s}</strong><span>{plants.filter(p=>p.sector===s).length} plantas · {property.crop}</span><div><StatusTag state={plants.filter(p=>p.sector===s).some(p=>p.state==="alert")?"alert":"baseline"}/><ChevronRight size={15}/></div></div></button>)}</div></div></>
  if(view==="Relatórios") return <><div className="welcome-row"><div><div className="eyebrow">DADOS PARA ACOMPANHAMENTO</div><h1>Relatórios</h1><p>Visualize e exporte um resumo dos dados demonstrativos.</p></div><button className="button-primary" onClick={onCsv}><Download size={15}/> Exportar CSV</button></div><div className="report-filters panel"><div><label>Propriedade</label><select value={property.id} onChange={event=>onSelectProperty(event.target.value)}>{properties.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></div><div><label>Período</label><select><option>Últimas 24 horas</option><option>Últimos 7 dias</option></select></div><div><label>Setor</label><select><option>Todos os setores</option>{sectors.map(s=><option key={s}>{s}</option>)}</select></div><button className="button-secondary" onClick={onCsv}><Filter size={14}/> Aplicar filtros</button></div><div className="report-grid"><div className="panel report-card"><span className="report-icon"><Flower2/></span><span>PLANTAS MONITORADAS</span><b>{plants.length}</b><small>Atualizado às 10:45 · dados demonstrativos</small><MiniChart height={74}/></div><div className="panel report-card"><span className="report-icon amber"><Activity/></span><span>ALTERAÇÕES REGISTRADAS</span><b>{plants.filter(p=>p.state==="alert"||p.state==="observation").length}</b><small>Dados ilustrativos</small><MiniChart color="#d59d32" height={74}/></div><div className="panel report-card"><span className="report-icon blue"><Signal/></span><span>QUALIDADE MÉDIA</span><b>96<small>%</small></b><small>Média simulada do sinal</small><MiniChart color="#6a9fb8" height={74}/></div></div><div className="panel report-preview"><div className="panel-heading"><div><div className="panel-title">Prévia do relatório</div><p>Resumo por planta · valores de demonstração</p></div><button className="text-button" onClick={onCsv}><Download size={14}/> Baixar CSV</button></div><div className="table-scroll"><table><thead><tr><th>PLANTA</th><th>SETOR</th><th>CONDIÇÃO</th><th>UMIDADE DO SOLO</th><th>QUALIDADE</th></tr></thead><tbody>{plants.slice(0,6).map(p=><tr key={p.id} onClick={()=>onPlant(p.id)}><td><strong>{p.id}</strong></td><td>{p.sector}</td><td><StatusTag state={p.state}/></td><td>{p.soil}%</td><td>{p.quality?`${p.quality}%`:"Sem dados"}</td></tr>)}</tbody></table></div><div className="science-note"><FileText size={15}/> Exportação CSV disponível. Relatório PDF requer integração futura.</div></div></>
  if(view==="Análise de IA") return <IntelligenceAnalysis property={property} plants={plants} alerts={alerts} onPlant={onPlant}/>
  if(view==="Intelligence Engine") return <><div className="welcome-row"><div><div className="eyebrow">MOTOR DE ANÁLISE · VERSÃO DEMONSTRATIVA</div><h1>Intelligence Engine</h1><p>Da coleta de dados à apresentação transparente de hipóteses.</p></div><span className="demo-badge large">SEM MODELO CIENTÍFICO CONECTADO</span></div><div className="engine-flow panel">{[{n:"01",t:"Recebimento",d:"Sinais e sensores"},{n:"02",t:"Qualidade",d:"Integridade dos dados"},{n:"03",t:"Processamento",d:"Normalização"},{n:"04",t:"Linha de base",d:"Contexto individual"},{n:"05",t:"Hipóteses",d:"Exige verificação"}].map((x,i)=><div className="engine-step" key={x.n}><span>{x.n}</span><b>{x.t}</b><small>{x.d}</small>{i<4&&<ArrowRight size={15}/>}</div>)}</div><div className="engine-grid"><div className="panel analysis-result"><div className="panel-heading"><div><div className="panel-title">Análise ilustrativa · T-024</div><p>17 nov. 2026 às 10:42 · valores simulados</p></div><span className="priority-label alta">Requer verificação</span></div><div className="analysis-hypothesis"><span>HIPÓTESE PRINCIPAL</span><h2>Possível alteração compatível com déficit hídrico</h2><p>Exemplo de interface para uma hipótese demonstrativa, não resultado de modelo científico validado.</p></div><div className="evidence-grid"><div><b>Evidências demonstrativas</b><p>Variação em relação à linha de base individual; umidade do solo simulada abaixo da faixa ilustrativa.</p></div><div><b>Limitações e verificações</b><p>Requer inspeção visual, conferência do sensor e contexto de manejo. Não recomenda irrigação.</p></div></div><div className="confidence-row"><span>Confiança apresentada</span><b>Moderada · simulada</b></div></div><div className="panel contribution-panel"><div className="panel-title">Fontes consideradas</div><p>Visualização demonstrativa de contribuição, sem inferência real.</p>{[{t:"Sinal eletrofisiológico",v:82,c:"green"},{t:"Umidade do solo",v:68,c:"amber"},{t:"Histórico individual",v:46,c:"blue"},{t:"Qualidade do sinal",v:91,c:"green"}].map(x=><div className="contribution" key={x.t}><span>{x.t}</span><b>{x.v}%</b><div><i className={x.c} style={{width:`${x.v}%`}}/></div></div>)}<div className="science-note"><Lightbulb size={14}/> Percentuais são apenas elementos visuais demonstrativos, não pesos do modelo.</div></div></div></>
  if(view==="Histórico e intervenções") return <><div className="welcome-row"><div><div className="eyebrow">RASTREABILIDADE</div><h1>Histórico e intervenções</h1><p>Eventos vinculados a cada indivíduo, sem assumir causalidade.</p></div><button className="button-primary" onClick={()=>window.dispatchEvent(new Event("siaf-add-note"))}><Plus size={15}/> Registrar evento</button></div><div className="panel history-panel"><div className="panel-heading"><div><div className="panel-title">Linha do tempo da propriedade</div><p>Últimas atividades · registros demonstrativos</p></div><select className="small-select"><option>Todas as plantas</option><option>T-024</option></select></div><div className="timeline">{timeline.filter(e=>plants.some(plant=>plant.id===e.plantId)).map(e=><button className="timeline-item timeline-button" key={e.id} onClick={()=>onPlant(e.plantId)}><div className="timeline-mark"><History size={14}/></div><div><strong>{e.type} <span>{e.plantId}</span></strong><p>{e.description}</p><small>{e.date} · {e.person}</small></div><ChevronRight size={15}/></button>)}</div></div></>
  if(view==="Dispositivos e sensores") {
    const offlineDevices=plants.filter(p=>p.state==="offline");
    const onlineDevices=plants.filter(p=>p.state!=="offline");
    return <><div className="welcome-row"><div><div className="eyebrow">INVENTÁRIO DE HARDWARE</div><h1>Dispositivos e sensores</h1><p>Rastreamento de conectividade de nós distributivos.</p></div><span className="connection-status"><span className="connection-pulse"/> {onlineDevices.length} de {plants.length} conectados</span></div><div className="device-summary"><div className="summary-stat"><span className="stat-label">Online</span><b>{onlineDevices.length}</b></div><div className={`summary-stat ${offlineDevices.length>0?"critical":""}`}><span className="stat-label">Offline</span><b>{offlineDevices.length}</b></div></div><div className="device-sections"><section><h3>Nós Conectados ({onlineDevices.length})</h3><div className="device-grid">{onlineDevices.map((p,i)=><div className="panel device-card" key={p.id}><div className="device-top"><span className="device-icon"><CheckCircle2 size={18}/></span><span className="device-state online"><i/>Ativo</span></div><h3>{p.deviceId}</h3><p>{p.id} · {p.sector}</p><div className="device-specs"><span>Modelo<b>SIA Node v2</b></span><span>Firmware<b>1.4.2-demo</b></span><span>Bateria<b>86%</b></span><span>Última comunicação<b>há 2 min</b></span></div><div className="sensor-chips"><span><Zap size={11}/>Eletrofisiologia</span><span><Droplets size={11}/>Umidade do solo</span><span><Thermometer size={11}/>Temperatura</span></div></div>)}</div></section>{offlineDevices.length>0&&<section><h3>Nós Offline ({offlineDevices.length})</h3><div className="device-grid">{offlineDevices.map(p=><div className="panel device-card offline" key={p.id}><div className="device-top"><span className="device-icon"><AlertCircle size={18}/></span><span className="device-state offline"><i/>Sem comunicação</span></div><h3>{p.deviceId}</h3><p>{p.id} · {p.sector}</p><div className="device-specs"><span>Modelo<b>SIA Node v2</b></span><span>Firmware<b>1.4.2-demo</b></span><span>Bateria<b>—</b></span><span>Última comunicação<b>há 42 min</b></span></div><div className="sensor-chips offline"><span><Zap size={11}/>Eletrofisiologia</span><span><Droplets size={11}/>Umidade do solo</span><span><Thermometer size={11}/>Temperatura</span></div></div>)}</div></section>}</div><div className="science-note wide"><Wifi size={15}/> Dados de nós conectados, bateria e última comunicação são demonstrativos.</div></>
  }
  return <><div className="welcome-row"><div><div className="eyebrow">PREFERÊNCIAS DO AMBIENTE DEMONSTRATIVO</div><h1>Configurações</h1><p>Preferências locais desta sessão e informações do protótipo.</p></div></div><div className="settings-grid"><section className="panel settings-card"><span className="settings-icon"><Settings2/></span><h3>Preferências de visualização</h3><p>Defina como os dados demonstrativos são exibidos para você.</p><label className="setting-line"><span>Unidade de temperatura</span><select><option>Celsius (°C)</option><option>Fahrenheit (°F)</option></select></label><label className="setting-line"><span>Alertas no painel</span><input type="checkbox" defaultChecked/></label><label className="setting-line"><span>Movimento reduzido</span><input type="checkbox" onChange={e=>document.documentElement.classList.toggle("reduce-motion",e.target.checked)}/></label></section><section className="panel settings-card"><span className="settings-icon"><ShieldCheck/></span><h3>Sobre os dados</h3><p>O S.I.A.F. está em modo de demonstração. Dados, sensores e hipóteses apresentados são simulados.</p><div className="settings-info"><span>Persistência</span><b>Somente durante esta sessão</b></div><div className="settings-info"><span>Integração IoT</span><b>Não conectada</b></div><div className="settings-info"><span>Modelo científico</span><b>Não conectado</b></div></section></div></>
}

export function SiafApp() {
  const [view,setView]=useState<View>("Visão geral"); const [plants,setPlants]=useState(seedPlants); const [alerts,setAlerts]=useState<Alert[]>(initialAlerts); const [timeline,setTimeline]=useState(initialTimeline); const [selectedPropertyId,setSelectedPropertyId]=useState(propertySeeds[0].id); const [propertyMenuOpen,setPropertyMenuOpen]=useState(false); const [selectedPlant,setSelectedPlant]=useState<string|null>(null); const [sector,setSector]=useState("Todos os setores"); const [sidebarOpen,setSidebarOpen]=useState(false); const [search,setSearch]=useState(""); const [dialog,setDialog]=useState<"plant"|"note"|null>(null); const [plantDraft,setPlantDraft]=useState(""); const [noteDraft,setNoteDraft]=useState(""); const [eventPlantId,setEventPlantId]=useState(""); const [eventType,setEventType]=useState("Inspeção visual"); const [eventDate,setEventDate]=useState("")
  const mainRef=useRef<HTMLElement>(null)
  const currentProperty=useMemo(()=>propertySeeds.find(property=>property.id===selectedPropertyId)??propertySeeds[0],[selectedPropertyId])
  const propertyPlants=useMemo(()=>plants.filter(plant=>plant.propertyId===selectedPropertyId),[plants,selectedPropertyId])
  const propertyAlerts=useMemo(()=>alerts.filter(alert=>propertyPlants.some(plant=>plant.id===alert.plantId)),[alerts,propertyPlants])
  const selectProperty=useCallback((id:string)=>{setSelectedPropertyId(id);setSelectedPlant(null);setSector("Todos os setores");setPropertyMenuOpen(false);setSidebarOpen(false)},[])
  const openEvent=useCallback((plantId?:string)=>{setEventPlantId(plantId??"");setEventType("Inspeção visual");setEventDate(new Date().toISOString().slice(0,16));setNoteDraft("");setDialog("note")},[])
  const navigate=useCallback((next:View)=>{setSelectedPlant(null);setView(next);setSidebarOpen(false)},[])
  const openPlant=useCallback((id:string)=>{setSelectedPlant(id);setView("Plantas monitoradas");setSidebarOpen(false)},[])
  const handleGlobalEvents=useCallback((e:Event)=>{if(e.type==="siaf-add-plant")setDialog("plant");if(e.type==="siaf-add-note")openEvent();if(e instanceof CustomEvent&&e.type==="siaf-update-alert")setAlerts(prev=>prev.map(a=>a.id===e.detail.id?e.detail:a));if(e instanceof CustomEvent&&e.type==="siaf-navigate")navigate(e.detail as View)},[navigate,openEvent])
  useEffect(()=>{window.addEventListener("siaf-add-plant",handleGlobalEvents);window.addEventListener("siaf-add-note",handleGlobalEvents);window.addEventListener("siaf-update-alert",handleGlobalEvents);window.addEventListener("siaf-navigate",handleGlobalEvents);return()=>{window.removeEventListener("siaf-add-plant",handleGlobalEvents);window.removeEventListener("siaf-add-note",handleGlobalEvents);window.removeEventListener("siaf-update-alert",handleGlobalEvents);window.removeEventListener("siaf-navigate",handleGlobalEvents)}},[handleGlobalEvents])
  useEffect(()=>{if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;const ctx=gsap.context(()=>{gsap.fromTo(".page-content > *",{y:8,opacity:0},{y:0,opacity:1,duration:.36,stagger:.035,ease:"power2.out"})},mainRef);return()=>ctx.revert()},[view,selectedPlant])
  const alertCount=propertyAlerts.filter(a=>a.status==="Requer verificação"||a.status==="Em análise").length
  const exportCsv=()=>{const rows=[["planta","setor","condicao","umidade_solo","temperatura","dispositivo","sensor","timestamp","qualidade","origem","processamento"],...propertyPlants.flatMap(p=>measurements.filter(m=>m.plantId===p.id&&m.variable==="Umidade do solo").slice(-1).map(m=>[p.id,p.sector,stateLabel[p.state],p.soil,p.temperature,p.deviceId,m.sensorId,m.timestamp,m.quality,m.origin,m.processing]))];const csv="\uFEFF"+rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\n");const link=document.createElement("a");link.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));link.download="siaf-relatorio-demonstrativo.csv";link.click();URL.revokeObjectURL(link.href)}
  const registerPlant=(e:React.FormEvent)=>{e.preventDefault();const id=plantDraft.trim().toUpperCase();if(!id)return;if(plants.some(plant=>plant.id===id)){const field=document.querySelector<HTMLInputElement>(".dialog-card .form-label input");field?.setCustomValidity("Este identificador já está cadastrado.");field?.reportValidity();return}setPlants(prev=>[{id,propertyId:selectedPropertyId,sector:sector==="Todos os setores"?"Estufa A":sector,species:"Solanum lycopersicum",variety:currentProperty.crop,stage:"Vegetativo",state:"offline",deviceId:"Aguardando vínculo",quality:0,soil:0,temperature:0,registered:"17/11/2026"},...prev]);setPlantDraft("");setDialog(null);setSelectedPlant(id);setView("Plantas monitoradas")}
  const registerNote=(e:React.FormEvent)=>{e.preventDefault();if(!eventPlantId||!noteDraft.trim())return;const at=new Date(eventDate);const event={id:`H-${Date.now()}`,plantId:eventPlantId,type:eventType,description:noteDraft.trim(),date:`${at.toLocaleDateString("pt-BR")} · ${at.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}`,person:"Ana Oliveira"};setTimeline(prev=>[event,...prev]);setNoteDraft("");setEventPlantId("");setDialog(null)}
  const currentPlant=selectedPlant?propertyPlants.find(p=>p.id===selectedPlant):undefined
  const filteredPlants=useMemo(()=>sector==="Todos os setores"?propertyPlants:propertyPlants.filter(p=>p.sector===sector),[propertyPlants,sector])
  const pageView=selectedPlant&&currentPlant?<PlantProfile plant={currentPlant} plants={propertyPlants} timeline={timeline} onBack={()=>setSelectedPlant(null)} onAddNote={()=>openEvent(selectedPlant)}/>:view==="Visão geral"?<Dashboard property={currentProperty} plants={filteredPlants} allPlants={propertyPlants} alerts={propertyAlerts} onPlant={openPlant} onAlerts={()=>navigate("Central de alertas")} sector={sector} setSector={setSector} setView={navigate}/>:<GenericView view={view} property={currentProperty} properties={propertySeeds} selectedPropertyId={selectedPropertyId} plants={view==="Dispositivos e sensores"||view==="Central de alertas"||view==="Alertas"||view==="Análise de IA"?propertyPlants:filteredPlants} alerts={propertyAlerts} timeline={timeline} setView={navigate} onPlant={openPlant} onCsv={exportCsv} onSelectProperty={selectProperty} onSelectSector={setSector} sector={sector}/>
  const searchAction=()=>{const p=propertyPlants.find(x=>x.id.toLowerCase()===search.trim().toLowerCase()||x.sector.toLowerCase().includes(search.trim().toLowerCase()));if(p)openPlant(p.id);else navigate("Plantas monitoradas")}
  return <div className={`siaf-shell ${sidebarOpen?"sidebar-open":""}`}><div className="mobile-overlay" onClick={()=>setSidebarOpen(false)}/><aside className="sidebar"><div className="brand-row"><span className="brand-symbol"><Leaf size={21}/></span><div><b>S.I.A.F.</b><small>INTELIGÊNCIA FITOLÓGICA</small></div><button className="sidebar-close" onClick={()=>setSidebarOpen(false)} aria-label="Fechar menu"><X size={18}/></button></div><div className="property-picker"><button type="button" className="property-switch" aria-expanded={propertyMenuOpen} aria-haspopup="menu" onClick={()=>setPropertyMenuOpen(value=>!value)}><span className="property-switch-icon"><Map size={15}/></span><span><small>PROPRIEDADE ATUAL</small><b>{currentProperty.name}</b></span><ChevronDown size={15}/></button>{propertyMenuOpen&&<div className="property-menu" role="menu" aria-label="Selecionar propriedade">{propertySeeds.map(item=><button type="button" role="menuitemradio" aria-checked={item.id===selectedPropertyId} className={item.id===selectedPropertyId?"selected":""} key={item.id} onClick={()=>selectProperty(item.id)}><span className="property-menu-icon"><Map size={14}/></span><span className="property-menu-name"><b>{item.name}</b><small>{item.location} · {item.area}</small></span>{item.id===selectedPropertyId&&<Check size={15}/>}</button>)}</div>}</div><div className="nav-scroll">{navGroups.map(group=><div className="nav-section" key={group.label}><span className="nav-caption">{group.label}</span>{group.items.map(item=><button className={`nav-item ${view===item.name&&!selectedPlant?"active":""}`} key={item.name} onClick={()=>navigate(item.name)}><item.icon size={17}/><span>{item.name}</span>{item.name==="Central de alertas"&&alertCount>0&&<b className="nav-count">{alertCount}</b>}</button>)}</div>)}</div><button className={`nav-item settings-nav ${view==="Configurações"?"active":""}`} onClick={()=>navigate("Configurações")}><Settings2 size={17}/><span>Configurações</span></button><div className="sidebar-bottom"><div className="demo-mode"><span className="demo-mode-icon"><Activity size={15}/></span><span><b>Ambiente demonstrativo</b><small>Dados simulados nesta sessão</small></span><span className="demo-mode-dot"/></div><div className="account-button"><span className="user-avatar">AO</span><span><b>Ana Oliveira</b><small>Gestora da propriedade</small></span></div></div></aside><div className="app-frame"><Header propertyName={currentProperty.name} onMenu={()=>setSidebarOpen(true)} onSearch={searchAction} onAlerts={()=>navigate("Central de alertas")} alerts={propertyAlerts} count={alertCount} search={search} setSearch={setSearch}/><main className="main-content" ref={mainRef}><div className="context-strip"><span className="context-dot"/><span>{currentProperty.name}</span><span>/</span><select value={sector} onChange={e=>setSector(e.target.value)} aria-label="Filtrar por setor"><option>Todos os setores</option>{sectors.map(s=><option key={s}>{s}</option>)}</select><span className="context-updated"><Clock3 size={12}/> Atualizado há 2 min <span className="context-divider"/> <span className="context-demo">DADOS DE DEMONSTRAÇÃO</span></span></div><div className="page-content">{pageView}</div></main><footer className="app-footer"><span>© 2026 S.I.A.F. <span>·</span> Plataforma de inteligência fitológica</span><span>Ambiente demonstrativo <i/></span></footer></div>{dialog&&<div className="dialog-backdrop" role="presentation" onMouseDown={e=>e.target===e.currentTarget&&setDialog(null)}><form className="dialog-card" onSubmit={dialog==="plant"?registerPlant:registerNote}><button type="button" className="dialog-close" onClick={()=>setDialog(null)} aria-label="Fechar"><X size={18}/></button><div className="dialog-icon">{dialog==="plant"?<Flower2 size={20}/>:<History size={20}/>}</div><h2>{dialog==="plant"?"Cadastrar planta":"Registrar evento"}</h2><p>{dialog==="plant"?"O cadastro ficará disponível nesta sessão. O vínculo do dispositivo pode ser feito posteriormente.":"Vincule o registro a uma planta e informe o tipo, o momento e o contexto da atividade."}</p>{dialog==="plant"?<><label className="form-label">Identificador da planta<input required pattern="[A-Za-z]-[0-9]{3}" title="Use o formato T-049" value={plantDraft} onChange={e=>{e.currentTarget.setCustomValidity("");setPlantDraft(e.target.value)}} placeholder="Ex.: T-049"/></label><label className="form-label">Setor<select value={sector==="Todos os setores"?"Estufa A":sector} onChange={e=>setSector(e.target.value)}>{sectors.map(s=><option key={s}>{s}</option>)}</select></label></>:<><label className="form-label">Planta<select required value={eventPlantId} onChange={e=>setEventPlantId(e.target.value)}><option value="">Selecionar planta</option>{propertyPlants.map(plant=><option key={plant.id} value={plant.id}>{plant.id} · {plant.sector}</option>)}</select></label><label className="form-label">Tipo de evento<select value={eventType} onChange={e=>setEventType(e.target.value)}><option>Inspeção visual</option><option>Irrigação</option><option>Adubação</option><option>Poda ou tutoramento</option><option>Calibração do sensor</option><option>Aplicação de defensivo</option><option>Outro</option></select></label><label className="form-label">Data e hora<input required type="datetime-local" value={eventDate} onChange={e=>setEventDate(e.target.value)}/></label><label className="form-label">O que foi observado ou realizado<textarea required minLength={8} rows={4} value={noteDraft} onChange={e=>setNoteDraft(e.target.value)} placeholder="Registre evidências, ação realizada e contexto…"/></label></>}<div className="dialog-demo"><CircleHelp size={14}/> Registro demonstrativo; não será sincronizado com outros usuários.</div><div className="dialog-actions"><button type="button" className="button-secondary" onClick={()=>setDialog(null)}>Cancelar</button><button type="submit" className="button-primary">{dialog==="plant"?"Cadastrar planta":"Registrar evento"}</button></div></form></div>}</div>
}
